"""Render a searchable, self-contained bilingual-source Chinese skill map."""
from __future__ import annotations

import json
from pathlib import Path


def render(snapshot: dict) -> str:
    payload = json.dumps(snapshot, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return TEMPLATE.replace("__ATLAS_JSON__", payload)


def write_html(snapshot: dict, output: Path) -> Path:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render(snapshot), encoding="utf-8")
    return output


TEMPLATE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>技能地图</title><link rel="icon" href="data:,"><style>
:root{color-scheme:dark;--ink:#eef3ff;--muted:#a6b4cb;--blue:#82b7ff;--line:#ffffff20}*{box-sizing:border-box}body{margin:0;background:#080a0f;color:var(--ink);font:14px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}button,input,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,.node:focus-visible{outline:2px solid #8abaff;outline-offset:4px}::selection{background:#2e64a8;color:white}*{scrollbar-width:thin;scrollbar-color:#43536e #10131c}header{height:90px;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}h1{font-size:25px;font-weight:650;letter-spacing:-.03em;margin:0}header p{margin:1px 0;color:var(--muted);font-size:12px}#host{color:var(--blue)}.stats{display:flex;gap:25px;color:var(--muted);font-size:12px}.stats strong{font-size:20px;color:var(--ink);margin-right:5px;font-variant-numeric:tabular-nums}.toolbar{display:flex;gap:10px;align-items:center;padding:12px 28px;border-bottom:1px solid var(--line)}input,select,.toolbar button,.map-controls button{background:#151923;border:1px solid #ffffff29;border-radius:8px;padding:8px 12px}.toolbar input{flex:1;min-width:100px;max-width:430px;caret-color:var(--blue)}input::placeholder{color:#a6b4cb}button:hover{border-color:#8abaff;background-color:#253348}.layout{display:grid;grid-template-columns:225px minmax(0,1fr) 300px;height:calc(100dvh - 155px);min-height:450px}aside,.details{background:#0f121a;padding:22px 18px;overflow:auto}aside{border-right:1px solid var(--line)}.details{border-left:1px solid var(--line)}.panel-title{font-size:15px;margin:0 0 20px;font-weight:600}.category{display:flex;align-items:center;gap:8px;justify-content:space-between;width:100%;text-align:left;border:1px solid transparent;background:transparent;border-radius:8px;padding:9px 10px;margin:2px 0}.category span:last-child{color:var(--muted);font-size:11px}.category.child{width:calc(100% - 18px);margin-left:18px;font-size:12px}.category.active{background:#223b60;border-color:#6088bc}.chevron{display:inline-block;width:12px;color:var(--blue)}.legend{font-size:12px;color:var(--muted);margin-top:25px}.legend p{margin:6px 0}main{min-width:0;position:relative;overflow:hidden;background-color:#05070b;background-image:linear-gradient(#ffffff0d 1px,transparent 1px),linear-gradient(90deg,#ffffff0d 1px,transparent 1px);background-size:40px 40px}#canvas{width:100%;height:100%;display:block;touch-action:none;cursor:grab}#canvas.dragging{cursor:grabbing}.edge{fill:none;stroke:#dde6f1;stroke-width:1.4;stroke-dasharray:2 6;opacity:.6}.node{cursor:pointer;outline:none}.node .plate{fill:url(#glass);stroke:#c8d3e4;stroke-width:1.2}.node .inner{fill:none;stroke:#ffffff30;pointer-events:none}.node.category-node .plate{stroke:#9dc7ff;filter:url(#glow)}.node.subcategory-node .plate{stroke:#6387b7}.node text{fill:#eff5ff;text-anchor:middle;pointer-events:none;font-size:14px}.node.skill-node text{font-size:12px}.node .count{font-size:10px;fill:#a8c3e7}.node.selected .plate,.node:hover .plate,.node:focus-visible .plate{stroke:#fff;stroke-width:2.5;fill:#25436a}.center-node .orb{fill:url(#blue);stroke:#b1d5ff;stroke-width:2;filter:url(#glow)}.center-node .ring{fill:none;stroke:#c9dfff;stroke-width:1.3;opacity:.75}.center-node .host-label{font-size:25px;font-weight:750;letter-spacing:-.03em}.center-node .count{font-size:11px}.map-controls{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);display:flex;gap:6px;background:#0d111de8;padding:6px;border:1px solid #ffffff20;border-radius:12px;white-space:nowrap}.map-controls button{padding:6px 11px;font-size:12px}.map-note{position:absolute;top:16px;left:18px;font-size:11px;color:#a6b4cb;pointer-events:none}.details h2{font-size:20px;line-height:1.4;overflow-wrap:anywhere;margin:0 0 24px}.details h3{font-size:12px;color:#a3b6d0;margin:24px 0 8px;font-weight:500}.details p{line-height:1.9;overflow-wrap:anywhere;margin:8px 0}.tag{display:inline-block;background:#1d2a3d;border:1px solid #405779;border-radius:6px;padding:4px 7px;margin:3px 4px 3px 0;font-size:12px;overflow-wrap:anywhere;max-width:100%}.path{font-size:12px;color:#a8b8ce;font-family:ui-monospace,monospace}.muted-note{color:var(--muted);font-size:12px}.close{float:right;background:none;border:0;font-size:21px;color:var(--muted)}.detail-skill{display:block;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--line);padding:10px 0;overflow-wrap:anywhere}.empty{position:absolute;top:45%;width:100%;text-align:center;color:var(--muted)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1100px){.layout{grid-template-columns:185px minmax(0,1fr)}.details{position:fixed;z-index:5;right:0;top:0;height:100dvh;width:310px;max-width:90vw;transform:translateX(100%);box-shadow:-15px 10px 40px #0008}.details.open{transform:translateX(0)}}
@media(min-width:1101px){.close{display:none}}
@media(max-width:650px){header{padding:12px 16px;height:80px}h1{font-size:22px}.stats{gap:10px}.stats strong{font-size:16px}.stats .warnings{display:none}header p{font-size:10px}.toolbar{padding:10px 12px;flex-wrap:wrap;gap:6px}.toolbar input{flex-basis:100%;max-width:none}.toolbar button,.toolbar select{padding:6px 8px;font-size:12px}.layout{display:flex;flex-direction:column;height:auto;min-height:0}aside{max-height:185px;border-bottom:1px solid var(--line);padding:12px 16px}.panel-title{margin-bottom:10px}.legend{display:none}main{height:65dvh;min-height:400px;flex:none}.map-controls{bottom:12px}.map-note{font-size:10px}#categories{display:flex;flex-wrap:wrap;align-items:start;gap:4px}.category{width:auto;padding:5px 9px}.category.child{width:auto;margin-left:8px}.details .panel-title{margin-bottom:22px}}
</style></head><body>
<header><div><h1>技能地图 <span id="host"></span></h1><p>从一个终端，探索你的全部技能</p></div><div class="stats"><div><strong id="skillCount">0</strong>技能</div><div><strong id="categoryCount">0</strong>分类</div><div class="warnings"><strong id="warningCount">0</strong>警告</div></div></header>
<div class="toolbar"><label class="sr-only" for="search">搜索技能</label><input id="search" placeholder="搜索技能名称、说明或触发词" autocomplete="off"><label class="sr-only" for="status">筛选状态</label><select id="status"><option value="all">全部状态</option><option value="valid">有效技能</option><option value="warning">有警告</option><option value="invalid">无法读取</option></select><button id="expand">全部展开</button><button id="collapse">全部收起</button><button id="reset">重置视图</button></div>
<div class="layout"><aside><h2 class="panel-title">分类列表</h2><div id="categories"></div><div class="legend"><p>一级分类 → 二级分类 → 技能</p><p>点击分类展开分支，选择技能查看说明。</p></div></aside><main><div class="map-note">双向技能脑图 · 拖动画布 · 滚轮缩放</div><svg id="canvas" role="group" aria-label="交互式技能脑图"></svg><div id="empty" class="empty" hidden>没有找到匹配的技能</div><div class="map-controls"><button id="zoomOut" aria-label="缩小">−</button><button id="fit">适应画布</button><button id="zoomIn" aria-label="放大">＋</button></div></main><section id="details" class="details" aria-live="polite"><button id="close" class="close" aria-label="关闭详情">×</button><h2 class="panel-title">详细说明</h2><div id="detailBody"><p class="muted-note">选择一个分类或技能。<br>这里会展示技能用途、原文触发说明和安装路径。</p></div></section></div>
<script>
const DATA=__ATLAS_JSON__;
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let state={query:'',status:'all',expanded:new Set(),selected:null,zoom:1,pan:{x:0,y:0}},graph=null,drag=null;
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function filtered(){const q=state.query.toLowerCase();return DATA.skills.filter(s=>(state.status==='all'||s.status===state.status)&&(!q||[s.name,s.description,s.summary,...s.triggers].join(' ').toLowerCase().includes(q)))}
function groups(list){const out=new Map();for(const s of list){if(!out.has(s.category))out.set(s.category,new Map());const ch=out.get(s.category),key=s.parent_category||'';if(!ch.has(key))ch.set(key,[]);ch.get(key).push(s)}return [...out].sort(([a],[b])=>a.localeCompare(b,'zh-CN'))}
const pk=p=>'cat:'+p,ck=(p,c)=>'sub:'+p+'::'+c;
function opened(id){return !!state.query||state.expanded.has(id)}
function renderSidebar(list){let h='';for(const [p,ch] of groups(list)){const id=pk(p),children=[...ch].filter(([c])=>c),members=[...ch.values()].flat();h+=`<button class="category ${state.selected===id?'active':''}" data-key="${esc(id)}" ${children.length?`aria-expanded="${opened(id)}"`:''}><span>${children.length?`<span class="chevron">${opened(id)?'▾':'▸'}</span>`:''}${esc(p)}</span><span>${members.length}</span></button>`;if(opened(id))for(const[c,m]of children)h+=`<button class="category child ${state.selected===ck(p,c)?'active':''}" data-key="${esc(ck(p,c))}"><span>${esc(c)}</span><span>${m.length}</span></button>`}$('categories').innerHTML=h;$('categories').querySelectorAll('button').forEach(b=>b.onclick=()=>chooseCategory(b.dataset.key))}
function tree(list){return groups(list).map(([p,ch])=>({id:pk(p),label:p,type:'category',members:[...ch.values()].flat(),children:opened(pk(p))?[...ch].flatMap(([c,m])=>c?[{id:ck(p,c),label:c,type:'subcategory',members:m,children:opened(ck(p,c))?m.map(skillNode):[]}]:m.map(skillNode)):[]}))}
function skillNode(s){return{id:s.id,label:s.name,type:'skill',skill:s,children:[]}}
function layout(list){const roots=tree(list),lanes=[[],[]],heights=[0,0],nodes=[],edges=[];function measure(n){n.span=n.children.length?Math.max(76,n.children.reduce((sum,c)=>sum+measure(c),0)):76;return n.span}for(const n of roots){measure(n);const side=heights[0]<=heights[1]?0:1;lanes[side].push(n);heights[side]+=n.span+30}function place(n,x,top,dir){n.x=x;n.y=top+n.span/2;nodes.push(n);let cursor=top;for(const c of n.children){place(c,x+dir*300,cursor,dir);edges.push([n,c]);cursor+=c.span}}for(let side=0;side<2;side++){let top=-heights[side]/2;for(const n of lanes[side]){place(n,side?320:-320,top,side?1:-1);edges.push([{x:0,y:0,type:'center'},n]);top+=n.span+30}}const xs=nodes.map(n=>n.x),ys=nodes.map(n=>n.y);return{nodes,edges,minX:Math.min(-110,...xs.map(x=>x-130)),maxX:Math.max(110,...xs.map(x=>x+130)),minY:Math.min(-110,...ys.map(y=>y-38)),maxY:Math.max(110,...ys.map(y=>y+38))}}
function el(tag,attrs,parent){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(parent)parent.appendChild(e);return e}
function fit(){state.zoom=1;state.pan={x:0,y:0};draw(false)}
function draw(refit=false){const list=filtered();if(refit){state.zoom=1;state.pan={x:0,y:0}}renderSidebar(list);$('skillCount').textContent=list.length;$('categoryCount').textContent=groups(list).length;$('warningCount').textContent=(DATA.warnings||[]).length+list.filter(s=>s.warnings.length).length;$('host').textContent='· '+DATA.host;const svg=$('canvas');svg.innerHTML=`<defs><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#72809a" stop-opacity=".43"/><stop offset=".45" stop-color="#202b3c" stop-opacity=".88"/><stop offset="1" stop-color="#0f131c" stop-opacity=".94"/></linearGradient><radialGradient id="blue" cx=".32" cy=".24" r=".85"><stop stop-color="#9cd0ff"/><stop offset=".4" stop-color="#397bea"/><stop offset="1" stop-color="#113876"/></radialGradient><filter id="glow" x="-50%" y="-70%" width="200%" height="240%"><feDropShadow dx="0" dy="3" stdDeviation="7" flood-color="#548aff" flood-opacity=".4"/></filter></defs>`;$('empty').hidden=!!list.length;graph=layout(list);const w=svg.clientWidth||800,h=svg.clientHeight||600;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);const scale=Math.min((w-45)/(graph.maxX-graph.minX),(h-110)/(graph.maxY-graph.minY),1.25)*state.zoom;graph.scale=scale;const midX=(graph.minX+graph.maxX)/2,midY=(graph.minY+graph.maxY)/2;const layer=el('g',{transform:`translate(${w/2+state.pan.x} ${h/2+state.pan.y}) scale(${scale}) translate(${-midX} ${-midY})`},svg);for(const[a,b]of graph.edges){const dir=b.x>a.x?1:-1,sx=a.x+dir*(a.type==='center'?95:120),ex=b.x-dir*120,mx=(sx+ex)/2;el('path',{d:`M ${sx} ${a.y} C ${mx} ${a.y},${mx} ${b.y},${ex} ${b.y}`,class:'edge'},layer)}for(const n of graph.nodes)node(layer,n);const center=el('g',{class:'node center-node',role:'button',tabindex:0,'aria-label':DATA.host,transform:'translate(0 0)'},layer);el('ellipse',{rx:111,ry:80,transform:'rotate(-24)',class:'ring'},center);el('circle',{r:88,class:'orb'},center);el('ellipse',{rx:108,ry:92,transform:'rotate(28)',class:'ring'},center);const title=el('text',{y:-3,class:'host-label'},center);title.textContent=DATA.host;el('text',{y:27,class:'count'},center).textContent=list.length+' 个技能';center.onclick=fit;center.onkeydown=e=>{if(e.key==='Enter')fit()}}
function node(parent,n){const g=el('g',{class:`node ${n.type}-node ${state.selected===n.id?'selected':''}`,role:'button',tabindex:0,'aria-label':n.label,'data-node-id':n.id,transform:`translate(${n.x} ${n.y})`},parent);if(n.type!=='skill')g.setAttribute('aria-expanded',opened(n.id));const height=n.type==='category'?60:52;el('rect',{x:-120,y:-height/2,width:240,height,rx:12,class:'plate'},g);el('rect',{x:-115,y:-height/2+5,width:230,height:height-10,rx:8,class:'inner'},g);el('title',{},g).textContent=n.label;const lines=n.type==='skill'&&n.label.length>29?[n.label.slice(0,29),n.label.slice(29)]:[n.label];lines.forEach((line,i)=>{const text=el('text',{y:lines.length>1?-3+i*16:(n.type==='skill'?5:0)},g);text.textContent=line;if(line.length>30){text.setAttribute('textLength','214');text.setAttribute('lengthAdjust','spacingAndGlyphs')}});if(n.type!=='skill')el('text',{y:18,class:'count'},g).textContent=n.members.length+' 个技能 · '+(opened(n.id)?'收起':'展开');const action=()=>n.type==='skill'?select(n.skill):chooseCategory(n.id);g.onclick=action;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}}}
function chooseCategory(id){let label='',members=[];for(const[p,ch]of groups(filtered())){if(id===pk(p)){label=p;members=[...ch.values()].flat()}for(const[c,m]of ch)if(id===ck(p,c)){label=c;members=m}}state.selected=id;state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);$('detailBody').innerHTML=`<h2>${esc(label)}</h2><p class="muted-note">此分类包含 ${members.length} 个技能</p>`;for(const s of members){const b=document.createElement('button');b.className='detail-skill';b.textContent=s.name;b.onclick=()=>{state.expanded.add(pk(s.category));if(s.parent_category)state.expanded.add(ck(s.category,s.parent_category));select(s)};$('detailBody').appendChild(b)}$('details').classList.add('open');draw(true)}
function select(s){state.selected=s.id;$('detailBody').innerHTML=`<h2>${esc(s.name)}</h2><h3>触发词</h3><div>${s.triggers.length?s.triggers.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):'<p class="muted-note">未能从技能说明提炼触发场景。</p>'}</div><h3>详细说明</h3><p>${esc(s.summary||'中文说明尚未生成，请重新构建。')}</p><h3>路径</h3><p class="path">${esc(s.path)}</p>`;$('details').classList.add('open');draw(false)}
function expandAll(){for(const[p,ch]of groups(filtered())){state.expanded.add(pk(p));for(const[c]of ch)if(c)state.expanded.add(ck(p,c))}draw(true)}
$('search').oninput=e=>{state.query=e.target.value;draw(true)};$('status').onchange=e=>{state.status=e.target.value;draw(true)};$('expand').onclick=expandAll;$('collapse').onclick=()=>{state.expanded.clear();draw(true)};$('reset').onclick=()=>{state={query:'',status:'all',expanded:new Set(),selected:null,zoom:1,pan:{x:0,y:0}};$('search').value='';$('status').value='all';$('details').classList.remove('open');expandAll()};$('close').onclick=()=>$('details').classList.remove('open');$('fit').onclick=fit;function zoom(f){state.zoom=Math.min(6,Math.max(.4,state.zoom*f));draw(false)}$('zoomIn').onclick=()=>zoom(1.25);$('zoomOut').onclick=()=>zoom(.8);$('canvas').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.1:1/1.1)},{passive:false});$('canvas').onpointerdown=e=>{if(e.target.closest('.node'))return;drag={x:e.clientX,y:e.clientY,pan:{...state.pan}};$('canvas').setPointerCapture(e.pointerId);$('canvas').classList.add('dragging')};$('canvas').onpointermove=e=>{if(!drag)return;state.pan={x:drag.pan.x+e.clientX-drag.x,y:drag.pan.y+e.clientY-drag.y};draw(false)};function stopDrag(){drag=null;$('canvas').classList.remove('dragging')}$('canvas').onpointerup=stopDrag;$('canvas').onpointercancel=stopDrag;window.addEventListener('resize',()=>draw(false));expandAll();
</script></body></html>'''
